using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "ApianLampOmenData", menuName = "Data/Battle/Omens System/Omen Data/Austra/ApianLampOmenData")]
public class ApianLampOmenData : GainSomethingWithDrawBackOmenData
{
	[SerializeField]
	private EffectsList effectsList;

	public override void Initialize(OmenInstance omenInstance)
	{
		ReferenceSingleton<AustraOmensHandler>.Instance.ApianLampOmenDataActive = true;
		base.Initialize(omenInstance);
	}

	public override void OmenRemoved()
	{
		ReferenceSingleton<AustraOmensHandler>.Instance.ApianLampOmenDataActive = false;
		base.OmenRemoved();
	}

	public override string OmenConvertedDescription()
	{
		return base.OmenConvertedDescription() + "\n" + Smart.Format(base.localizationManager.GetLocalizedDodgeCantBeLower(), effectsList.DodgeEffect.MinimumDodgeAmountOnAustra) + "\n" + GetOmenRawLocalizedDescription();
	}
}
